    // A GEDCOM file carries place names, not coordinates, so the imported
    // events have no map point yet. The demo project's synthetic city centres
    // are applied through the app's own "confirm place" command, exactly what
    // the map's clarify panel calls; the camera stays off for this setup.
    const placePoints = demoPlacePoints(demoDir);
    await exec(
      `window.__demoGeo = { status: "pending", applied: [] };
       const internals = window.__TAURI_INTERNALS__;
       const points = arguments[0];
       (async () => {
         const events = await internals.invoke("event_list", {});
         const pending = new Map();
         for (const item of events) {
           const event = item.entity ?? item.data ?? item;
           if (!event.place || event.placeGeo) continue;
           if (!points[event.place]) continue;
           const list = pending.get(event.place) ?? [];
           list.push(event.id);
           pending.set(event.place, list);
         }
         const applied = [];
         for (const [place, ids] of pending) {
           const result = await internals.invoke("event_place_geo_apply", {
             input: { eventIds: ids, expectedPlace: place, point: points[place] },
           });
           applied.push({ place, result });
         }
         return applied;
       })().then(
         (applied) => {
           window.__demoGeo = { status: "ok", applied };
         },
         (error) => {
           window.__demoGeo = { status: "error", message: String(error) };
         },
       );
       return true;`,
      [placePoints],
    );
    {
      const deadline = Date.now() + 20000;
      let state = null;
      while (Date.now() < deadline) {
        state = await exec("return window.__demoGeo;");
        if (state?.status !== "pending") break;
        await sleep(150);
      }
      if (state?.status !== "ok") {
        throw new Error(`map points setup failed: ${state?.message ?? "timeout"}`);
      }
      const summary = state.applied
        .map((item) => `${item.place}: ${item.result.applied}`)
        .join(", ");
      console.log(`  map points: ${summary}`);
    }

    // The imported archive has no "home person", so the tree would start from
